commands.code:
mkdir -p ~/dev-opps-lab/infra/policy19/tests ~/dev-opps-lab/infra/drift19/output ~/dev-opps-lab/evidence/week-19
cd ~/dev-opps-lab/infra/policy19
cat > main.tf <<'EOF'
terraform {
  required_version = ">= 1.10, < 2.0"
  required_providers { aws = { source = "hashicorp/aws", version = "~> 6.0" } }
}
provider "aws" { region = "us-east-1" }
variable "admin_cidr" {
  type = string
  default = "203.0.113.10/32"
  validation {
    condition = can(cidrhost(var.admin_cidr, 0)) && can(regex("^[0-9.]+/32$", var.admin_cidr))
    error_message = "The lab requires one valid IPv4 administrator address with /32."
  }
}
resource "aws_vpc" "lab" { cidr_block = "10.78.0.0/16" }
resource "aws_security_group" "admin" {
  name_prefix = "devopps-test-"
  vpc_id = aws_vpc.lab.id
}
resource "aws_vpc_security_group_ingress_rule" "ssh" {
  security_group_id = aws_security_group.admin.id
  ip_protocol = "tcp"
  from_port = 22
  to_port = 22
  cidr_ipv4 = var.admin_cidr
}
EOF
cat > tests/security.tftest.hcl <<'EOF'
mock_provider "aws" {}
run "only_one_admin" {
  command = plan
  assert {
    condition = aws_vpc_security_group_ingress_rule.ssh.cidr_ipv4 == "203.0.113.10/32" && aws_vpc_security_group_ingress_rule.ssh.from_port == 22 && aws_vpc_security_group_ingress_rule.ssh.to_port == 22
    error_message = "SSH must target the reviewed single administrator address."
  }
}
run "reject_world_open" {
  command = plan
  variables { admin_cidr = "0.0.0.0/0" }
  expect_failures = [var.admin_cidr]
}
EOF
cp ../local17/.gitignore .gitignore
terraform fmt -recursive
terraform init
terraform validate
terraform test
